// RDF4J's own SPARQL function and expression unit tests (function/string,
// hash, numeric, datetime, xsd, triple; util/QueryEvaluationUtilTest and the
// value comparators), run as data on @factoidal/core.
// Data: cases.json, derived from Eclipse RDF4J, Eclipse Distribution License
// 1.0 (BSD-3-Clause); see its _notice and the repository NOTICE. Generated by
// tools/moonforge-study/extract-expr.py. Verdicts: verdicts.json.
// This file is original to echochamber (Apache-2.0).
//
// Each case is ONE query. The engine evaluates the expression, the expected
// term and the check, and binds ?ok; JavaScript reads only ?ok (rule 1).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { core, coreVersion, loadJson, checkVerdicts, judge } from '../lib/harness.mjs';

const { cases, notPorted } = loadJson(new URL('./cases.json', import.meta.url));
const verdicts = loadJson(new URL('./verdicts.json', import.meta.url));
const ids = new Set(cases.map((c) => c.id));

const PROLOGUE = 'PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\nPREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>\n';
const XSD_BOOLEAN = 'http://www.w3.org/2001/XMLSchema#boolean';

const OK = {
  sameTerm: 'COALESCE(sameTerm(?r, ?e), false)',
  label: 'COALESCE(sameTerm(STR(?r), ?e), false)',
  datatype: 'COALESCE(sameTerm(DATATYPE(?r), ?e), false)',
  valueEqual: 'COALESCE(?r = ?e, false)',
  ebv: 'COALESCE(IF(?r, true, false) = ?e, false)',
  error: '!BOUND(?r)',
  noError: 'BOUND(?r)',
  parseError: 'true',
};
const ORDER = {
  lt: '?k1 = "a" && ?k2 = "a"',
  gt: '?k1 = "b" && ?k2 = "b"',
  eq: '?k1 = "a" && ?k2 = "b"',
  ne: '?k1 = ?k2',
};

/** The query of one case. */
export function caseQuery(c) {
  const pre = c.pre ? c.pre + ' ' : '';
  if (c.check === 'order') {
    // Two rows, keys "a" and "b"; an unbound value is a variable that is never bound.
    const v = (x) => (x === null ? '?unbound' : x);
    const inner = `{ ${pre}VALUES ?k { "a" "b" } BIND(IF(?k = "a", ${v(c.a)}, ${v(c.b)}) AS ?v) }`;
    // Sorted with the key as ascending and as descending tie-break: a strict
    // order puts the same row first both times, a tie does not.
    return PROLOGUE + 'SELECT ?ok WHERE {\n'
      + `  { SELECT (?k AS ?k1) WHERE ${inner} ORDER BY ?v ?k LIMIT 1 }\n`
      + `  { SELECT (?k AS ?k2) WHERE ${inner} ORDER BY ?v DESC(?k) LIMIT 1 }\n`
      + `  BIND((${ORDER[c.expected]}) AS ?ok)\n}`;
  }
  const ok = c.check === 'test' ? `COALESCE((${c.expected}), false)` : OK[c.check];
  assert.ok(ok, `${c.id}: unknown check ${c.check}`);
  const e = c.expected !== null && c.check !== 'test' ? `BIND((${c.expected}) AS ?e) ` : '';
  return PROLOGUE + `SELECT ?ok WHERE { ${pre}BIND((${c.expr}) AS ?r) ${e}BIND((${ok}) AS ?ok) }`;
}

const ds = await core.openDataset('', { format: 'turtle' });

export async function runCase(c) {
  let rows;
  try {
    rows = await ds.query(caseQuery(c), { version: c.sparql12 ? '1.2' : '1.1' });
  } catch (e) {
    if (c.check === 'parseError') return { pass: e.code === 'query.syntax', detail: `${e.code}: ${e.message}` };
    return { pass: false, detail: `${e.code}: ${e.message}` };
  }
  if (c.check === 'parseError') return { pass: false, detail: 'the query parsed' };
  if (!Array.isArray(rows) || rows.length !== 1) return { pass: false, detail: `expected one row, got ${rows && rows.length}` };
  const ok = rows[0].get('ok');
  const pass = !!ok && ok.termType === 'Literal' && ok.datatype.value === XSD_BOOLEAN && ok.value === 'true';
  return { pass, detail: pass ? '' : `?ok = ${ok ? ok.value : 'unbound'}` };
}

test(`RDF4J expression tests: ${cases.length} cases, ${notPorted.length} not ported, @factoidal/core ${coreVersion}`, () => {
  assert.equal(ids.size, cases.length, 'case ids are unique');
  checkVerdicts(verdicts, ids);
  for (const x of notPorted) assert.ok(x.id && x.file && x.reason, `not ported entry needs id, file and reason: ${JSON.stringify(x)}`);
  for (const id of notPorted.map((x) => x.id)) assert.ok(!ids.has(id), `${id} is both ported and not ported`);
});

for (const c of cases) {
  test(c.id + (verdicts.cases[c.id] ? ` [${verdicts.cases[c.id].verdict}]` : ''), async () => {
    judge(c.id, await runCase(c), verdicts);
  });
}
